    static List<Rect> SampleSpread(List<Rect> sorted,int limit,Func<Rect,double> movement){if(sorted.Count<=limit)return sorted;int near=limit/2;var chosen=sorted.Take(near).ToList();int remaining=limit-near;for(int i=1;i<=remaining;i++){int index=near+(int)Math.Floor((double)i*(sorted.Count-near)/(remaining+1));if(index>=sorted.Count)index=sorted.Count-1;chosen.Add(sorted[index]);}return chosen.GroupBy(x=>$"{x.X:F6}|{x.Y:F6}|{x.W:F6}|{x.D:F6}").Select(g=>g.First()).OrderBy(movement).ToList();}    static List<Rect> BuildCandidates(Rect s,Rect[] fixedBlocks,double sw,double sd){var rows=new List<Rect>();double maxW=sw-2*Margin,maxD=sd-2*Margin;var widths=new SortedSet<double>();for(double w=Math.Ceiling((s.Area/maxD)/Grid)*Grid;w<=maxW+Tol;w=Math.Round(w+Grid,8))widths.Add(w);widths.Add(s.W);widths.Add(maxW);foreach(double w in widths){double d=Math.Abs(w-s.W)<Tol?s.D:s.Area/w;if(d<=0||d>maxD+Tol)continue;foreach(double y in Positions(Margin,sd-Margin-d))foreach(double x in Positions(Margin,sw-Margin-w)){var q=new Rect(s.Id,x,y,w,d);if(Inside(q,sw,sd)&&!fixedBlocks.Any(o=>Overlap(q,o)))rows.Add(q);}}return rows.GroupBy(q=>$"{q.X:F6}|{q.Y:F6}|{q.W:F6}|{q.D:F6}").Select(g=>g.First()).OrderBy(q=>Move(s,q)).ThenBy(q=>q.Y).ThenBy(q=>q.X).ToList();}
